function fib(n) {
  const dp = new Array(n + 1).fill(0);
  if (n >= 1) dp[1] = 1;
  for (let i = 2; i <= n; i++) dp[i] = dp[i - 1] + dp[i - 2];   // both are already filled
  return dp[n];
}

